import { useState, useEffect, useCallback } from 'react'
import { useWriteContract, useAccount, useWaitForTransactionReceipt, useReadContract, usePublicClient } from 'wagmi'
import { useGuestChain } from './useGuestChain.js'
import { useConnectModal } from '@rainbow-me/rainbowkit'
import { isAddress, parseUnits, formatUnits } from 'viem'
import PctBtns from './PctBtns.jsx'
import { SAFE_ABI } from './abi.js'
import { getSafeAddress } from './config.js'
import { getChainInfo, getTxUrl, fmtDisplay, fmtErr } from './chainUtils.js'
import { guardianSalt, deriveAccount, validatePassword } from './safeUtils.js'
import { getTokens, NATIVE } from './tokenList.js'
import SafeAssets from './SafeAssets.jsx'

const ERC20_ABI = [
  { type:'function', name:'symbol',   inputs:[], outputs:[{type:'string'}], stateMutability:'view' },
  { type:'function', name:'decimals', inputs:[], outputs:[{type:'uint8'}],  stateMutability:'view' },
]

function sanitizeAmount(v) {
  return v.replace(/[^0-9.]/g, '').replace(/^(\d*\.?\d*).*$/, '$1')
}

// ── Send sub-tab ──────────────────────────────────────────────────────────────
function SendTab() {
  const { address } = useAccount()
  const { openConnectModal } = useConnectModal()
  const { activeChainId: chainId } = useGuestChain()
  const { currency } = getChainInfo(chainId)
  const publicClient = usePublicClient()
  const SAFE_ADDRESS = getSafeAddress(chainId)
  const presetTokens = getTokens(chainId)

  const [token, setToken] = useState(presetTokens[0])
  const [customAddr, setCustomAddr] = useState('')
  const [customErr, setCustomErr] = useState('')
  const [showCustom, setShowCustom] = useState(false)
  const [extraTokens, setExtraTokens] = useState({})
  const handleTokenLoaded = useCallback(t => setExtraTokens(prev => ({ ...prev, [t.address.toLowerCase()]: t })), [])

  function selectPreset(t) {
    setToken(t)
    setShowCustom(false)
    setCustomAddr('')
    setCustomErr('')
  }

  const [amount, setAmount] = useState('')
  const [to, setTo] = useState('')
  const [toErr, setToErr] = useState('')
  const [password, setPassword] = useState('')
  const [pwVerified, setPwVerified] = useState(null)
  const [txHash, setTxHash] = useState(null)
  const [status, setStatus] = useState('')
  const { writeContractAsync, isPending } = useWriteContract()
  const { isLoading: isConfirming, isSuccess } = useWaitForTransactionReceipt({ hash: txHash })

  const { data: vaultBalance, refetch: refetchBalance } = useReadContract({
    address: SAFE_ADDRESS, abi: SAFE_ABI, functionName: 'balances',
    args: [address ?? NATIVE, token.address],
    chainId,
    query: { enabled: !!address },
  })
  const { data: guardian } = useReadContract({
    address: SAFE_ADDRESS, abi: SAFE_ABI, functionName: 'guardians',
    args: [address ?? NATIVE],
    chainId,
    query: { enabled: !!address },
  })
  const { data: nonce } = useReadContract({
    address: SAFE_ADDRESS, abi: SAFE_ABI, functionName: 'nonces',
    args: [address ?? NATIVE],
    chainId,
    query: { enabled: !!address },
  })

  const hasGuardian = guardian !== undefined && guardian !== NATIVE

  useEffect(() => {
    setToken(getTokens(chainId)[0]); setAmount(''); setTo(''); setToErr('')
    setPassword(''); setPwVerified(null); setStatus(''); setTxHash(null)
    setShowCustom(false); setCustomAddr(''); setCustomErr(''); setExtraTokens({})
  }, [chainId]) // eslint-disable-line
  useEffect(() => { if (isSuccess) refetchBalance() }, [isSuccess]) // eslint-disable-line
  useEffect(() => {
    if (!to.trim()) { setToErr(''); return }
    setToErr(isAddress(to.trim()) ? '' : 'Invalid address')
  }, [to])
  useEffect(() => { setPwVerified(null) }, [password])

  async function verifyPw() {
    if (!hasGuardian || !password) return
    const acc = await deriveAccount(password, guardianSalt(chainId, address))
    setPwVerified(acc.address.toLowerCase() === guardian.toLowerCase())
  }

  async function resolveCustom(addr) {
    setCustomErr('')
    if (!addr || !isAddress(addr)) { setCustomErr('Invalid address'); return }
    try {
      const [sym, dec] = await Promise.all([
        publicClient.readContract({ address: addr, abi: ERC20_ABI, functionName: 'symbol' }),
        publicClient.readContract({ address: addr, abi: ERC20_ABI, functionName: 'decimals' }),
      ])
      setToken({ symbol: sym, address: addr.toLowerCase(), decimals: Number(dec) })
    } catch { setCustomErr('Could not read token') }
  }

  const balanceNum = vaultBalance !== undefined ? parseFloat(formatUnits(vaultBalance, token.decimals)) : null
  const amountNum = parseFloat(amount)
  const amountErr = amount && (isNaN(amountNum) || amountNum <= 0) ? 'Amount must be > 0'
    : amount && balanceNum !== null && amountNum > balanceNum ? `Exceeds balance (max ${fmtDisplay(vaultBalance, token.decimals)})` : ''
  const pwErr = hasGuardian ? validatePassword(password) : ''

  async function handleSend() {
    if (!amount || !address || amountErr || toErr || !to.trim()) return
    try {
      setStatus('info:Signing…')
      let sig = '0x'
      const amt = parseUnits(amount, token.decimals)
      if (hasGuardian) {
        if (pwErr) { setStatus('err:' + pwErr); return }
        const acc = await deriveAccount(password, guardianSalt(chainId, address))
        if (acc.address.toLowerCase() !== guardian.toLowerCase()) { setStatus('err:Wrong password'); return }
        sig = await acc.signTypedData({
          domain: { name: 'CloakCashSafe', version: '1', chainId, verifyingContract: SAFE_ADDRESS },
          types: { Transfer: [
            { name: 'user', type: 'address' }, { name: 'token', type: 'address' },
            { name: 'amount', type: 'uint256' }, { name: 'to', type: 'address' }, { name: 'nonce', type: 'uint256' },
          ]},
          primaryType: 'Transfer',
          message: { user: address, token: token.address, amount: amt, to: to.trim(), nonce: BigInt(nonce ?? 0) },
        })
      }
      setStatus('info:Confirm in wallet…')
      const hash = await writeContractAsync({
        address: SAFE_ADDRESS, abi: SAFE_ABI, functionName: 'internalTransfer',
        args: [token.address, amt, to.trim(), sig],
      })
      setTxHash(hash)
      setStatus('info:Confirming…')
    } catch (e) {
      setStatus('err:' + fmtErr(e))
    }
  }

  const txUrl = txHash ? getTxUrl(chainId, txHash) : null
  const displayStatus = isSuccess ? `ok:✅ Sent ${amount} ${token.symbol}` : status
  const [dtype, dmsg] = displayStatus.includes(':') ? displayStatus.split(/:(.+)/) : ['info', displayStatus]

  return (
    <div className="card">
      <h2>Internal Transfer</h2>
      <p className="sub">Send vault balance to another address. Recipient sees amount only — sender is not recorded in events.</p>

      <SafeAssets onTokensLoaded={handleTokenLoaded} />
      <div className="token-picker">
        {presetTokens.map(t => (
          <button key={t.address} className={`token-btn ${token.address === t.address ? 'active' : ''}`}
            onClick={() => selectPreset(t)}>{t.symbol}</button>
        ))}
        {Object.values(extraTokens)
          .filter(t => !presetTokens.find(p => p.address.toLowerCase() === t.address.toLowerCase()))
          .map(t => (
            <button key={t.address} className={`token-btn ${token.address === t.address.toLowerCase() ? 'active' : ''}`}
              onClick={() => selectPreset(t)}>{t.symbol}</button>
          ))}
        <button className={`token-btn ${showCustom ? 'active' : ''}`}
          onClick={() => setShowCustom(s => !s)}>+ Custom</button>
      </div>

      {showCustom && (
        <div style={{marginBottom:'12px'}}>
          <div className="token-custom-wrap">
            <input className={`token-custom-input ${customErr ? 'err' : ''}`}
              placeholder="Token contract address (0x…)"
              value={customAddr} onChange={e => setCustomAddr(e.target.value)}
              onBlur={() => resolveCustom(customAddr)} />
            <button className="btn-copy" onClick={() => resolveCustom(customAddr)}>Load</button>
          </div>
          {customErr && <div className="token-custom-label" style={{color:'#f43f5e'}}>{customErr}</div>}
          {!customErr && token.address === customAddr?.toLowerCase() && customAddr && (
            <div className="token-custom-label">✓ {token.symbol} · {token.decimals} decimals</div>
          )}
        </div>
      )}

      {true && (
        <div className={`input-panel ${amountErr ? 'input-err' : ''}`}>
          <div className="input-panel-label">Amount</div>
          <div className="input-panel-row">
            <input className="input-big" type="text" inputMode="decimal" placeholder="0"
              value={amount} onChange={e => setAmount(sanitizeAmount(e.target.value))} />
            <div className="input-currency"><span className="token-sym-dot" />{token.symbol}</div>
          </div>
          <div className="input-balance">
            <span>Vault: {balanceNum !== null ? `${fmtDisplay(vaultBalance, token.decimals)} ${token.symbol}` : '—'}</span>

          </div>
          {vaultBalance !== undefined && <PctBtns balance={vaultBalance} decimals={token.decimals} amount={amount} setAmount={setAmount} />}
        </div>
      )}
      {amountErr && <div className="status err" style={{marginTop:'-8px'}}>{amountErr}</div>}

      <input className={`input ${toErr ? 'input-err' : to && !toErr ? 'input-ok' : ''}`}
        placeholder="Recipient vault address (0x…)"
        value={to} onChange={e => setTo(e.target.value)} />
      {toErr && <div className="status err" style={{marginTop:'4px'}}>{toErr}</div>}

      {hasGuardian && (
        <>
          <input className={`input ${pwVerified === false ? 'input-err' : pwVerified === true ? 'input-ok' : password && pwErr ? 'input-err' : password && !pwErr ? 'input-ok' : ''}`}
            type="password" placeholder="Vault password (required)"
            value={password} onChange={e => setPassword(e.target.value)}
            onBlur={verifyPw} />
          {pwVerified === false && <div className="status err" style={{marginTop:'4px'}}>Wrong password</div>}
          {pwVerified === true  && <div className="status ok"  style={{marginTop:'4px'}}>✓ Password correct</div>}
        </>
      )}

      <button className="btn-primary" onClick={!address ? openConnectModal : handleSend}
        disabled={(!!address && (!amount || !!amountErr || !!toErr || !to.trim() || (hasGuardian && !!pwErr))) || isPending || isConfirming}>
        {isPending ? <><span className="spinner" /> Confirm in wallet…</>
          : isConfirming ? <><span className="spinner" /> Confirming…</>
          : !address ? 'Connect' : 'Send'}
      </button>
      {displayStatus && (
        <div className={`status ${dtype}`}>
          {dmsg}
          {txUrl && (isSuccess || isConfirming) && <> · <a href={txUrl} target="_blank" rel="noreferrer">View ↗</a></>}
        </div>
      )}
    </div>
  )
}

// ── Received sub-tab ──────────────────────────────────────────────────────────
const INTERNAL_RECEIVED_TOPIC = '0x' + Array.from(
  new TextEncoder().encode('InternalReceived(address,address,uint256)')
).reduce((h, b) => h, '') // placeholder — computed below via keccak

// keccak256 of event sig — precomputed
const TOPIC_INTERNAL_RECEIVED = '0x9b1bfa7fa9ee420a16e124f794c35ac9f90472acc99140eb2f6447c714cad8eb'

function ReceivedTab() {
  const { address } = useAccount()
  const { activeChainId: chainId } = useGuestChain()
  const publicClient = usePublicClient()
  const SAFE_ADDRESS = getSafeAddress(chainId)
  const presetTokens = getTokens(chainId)

  const [records, setRecords] = useState(null)
  const [loading, setLoading] = useState(false)
  const [manualHash, setManualHash] = useState('')
  const [manualResult, setManualResult] = useState(null)
  const [manualErr, setManualErr] = useState('')

  async function fetchReceived() {
    if (!address) return
    setLoading(true)
    try {
      const logs = await publicClient.getLogs({
        address: SAFE_ADDRESS,
        event: {
          type: 'event', name: 'InternalReceived',
          inputs: [
            { name: 'token',  type: 'address', indexed: true },
            { name: 'to',     type: 'address', indexed: true },
            { name: 'amount', type: 'uint256', indexed: false },
          ],
        },
        args: { to: address },
        fromBlock: 'earliest',
        toBlock: 'latest',
      })
      // enrich with block timestamp
      const enriched = await Promise.all(logs.map(async log => {
        const block = await publicClient.getBlock({ blockNumber: log.blockNumber })
        const tokenInfo = presetTokens.find(t => t.address.toLowerCase() === log.args.token.toLowerCase())
        const decimals = tokenInfo?.decimals ?? 18
        const symbol = tokenInfo?.symbol ?? log.args.token.slice(0, 8) + '…'
        return {
          txHash: log.transactionHash,
          token: log.args.token,
          symbol,
          decimals,
          amount: formatUnits(log.args.amount, decimals),
          time: new Date(Number(block.timestamp) * 1000).toLocaleString(),
          blockNumber: Number(log.blockNumber),
        }
      }))
      setRecords(enriched.reverse())
    } catch (e) {
      setRecords([])
    }
    setLoading(false)
  }

  async function lookupHash() {
    setManualErr('')
    setManualResult(null)
    const h = manualHash.trim()
    if (!h || !/^0x[0-9a-fA-F]{64}$/.test(h)) { setManualErr('Invalid tx hash'); return }
    try {
      const receipt = await publicClient.getTransactionReceipt({ hash: h })
      const log = receipt.logs.find(l =>
        l.address.toLowerCase() === SAFE_ADDRESS.toLowerCase() &&
        l.topics[0] === TOPIC_INTERNAL_RECEIVED &&
        l.topics[2]?.toLowerCase().endsWith(address?.slice(2).toLowerCase())
      )
      if (!log) { setManualErr('No InternalReceived event for your address in this tx'); return }
      // decode amount (last 32 bytes of data)
      const amount = BigInt(log.data)
      const tokenAddr = '0x' + log.topics[1].slice(26)
      const tokenInfo = presetTokens.find(t => t.address.toLowerCase() === tokenAddr.toLowerCase())
      const decimals = tokenInfo?.decimals ?? 18
      const symbol = tokenInfo?.symbol ?? tokenAddr.slice(0, 8) + '…'
      const block = await publicClient.getBlock({ blockNumber: receipt.blockNumber })
      setManualResult({
        txHash: h,
        token: tokenAddr, symbol, decimals,
        amount: formatUnits(amount, decimals),
        time: new Date(Number(block.timestamp) * 1000).toLocaleString(),
        blockNumber: Number(receipt.blockNumber),
      })
    } catch (e) {
      setManualErr(fmtErr(e))
    }
  }

  useEffect(() => { if (address) fetchReceived() }, [address]) // eslint-disable-line

  return (
    <div className="card">
      <h2>Received</h2>
      <p className="sub">Internal transfers received to your vault. Sender is not shown.</p>

      {/* Manual lookup */}
      <div style={{marginBottom:'16px'}}>
        <div className="token-custom-wrap">
          <input className={`token-custom-input ${manualErr ? 'err' : ''}`}
            placeholder="Lookup by tx hash (0x…)"
            value={manualHash} onChange={e => setManualHash(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && lookupHash()} />
          <button className="btn-copy" onClick={lookupHash}>Look up</button>
        </div>
        {manualErr && <div className="status err" style={{marginTop:'4px'}}>{manualErr}</div>}
        {manualResult && <RecordRow r={manualResult} chainId={chainId} highlight />}
      </div>

      {/* Chain scan */}
      <div style={{display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:'10px'}}>
        <span style={{fontSize:'13px', color:'var(--text2)'}}>Recent received</span>
        <button className="btn-copy" onClick={fetchReceived} disabled={loading}>
          {loading ? <><span className="spinner" /> Scanning…</> : '↻ Refresh'}
        </button>
      </div>

      {records === null && !loading && (
        <div className="status info">Connect wallet to scan received transfers.</div>
      )}
      {records !== null && records.length === 0 && (
        <div className="status info">No internal transfers received yet.</div>
      )}
      {records && records.map(r => <RecordRow key={r.txHash} r={r} chainId={chainId} />)}
    </div>
  )
}

function RecordRow({ r, chainId, highlight }) {
  const txUrl = getTxUrl(chainId, r.txHash)
  return (
    <div style={{
      background: highlight ? 'rgba(74,222,128,0.08)' : 'var(--glass2)',
      border: `1px solid ${highlight ? 'var(--accent)' : 'var(--border)'}`,
      borderRadius: '10px', padding: '12px 14px', marginBottom: '8px',
      fontSize: '13px',
    }}>
      <div style={{display:'flex', justifyContent:'space-between', alignItems:'center'}}>
        <span style={{color:'var(--accent)', fontWeight:600}}>+{r.amount} {r.symbol}</span>
        <span style={{color:'var(--text3)', fontSize:'11px'}}>{r.time}</span>
      </div>
      <div style={{color:'var(--text3)', fontSize:'11px', marginTop:'4px', display:'flex', gap:'12px'}}>
        <span>Block {r.blockNumber}</span>
        <a href={txUrl} target="_blank" rel="noreferrer" style={{color:'var(--accent2)'}}>View tx ↗</a>
      </div>
    </div>
  )
}

// ── Main export ───────────────────────────────────────────────────────────────
export default function SafeTransfer() {
  const [sub, setSub] = useState('send')
  return (
    <div>
      <div className="uc-tab-bar" style={{marginBottom:'12px'}}>
        <button className={`uc-tab-btn ${sub==='send' ? 'active' : ''}`} onClick={() => setSub('send')}>Send</button>
        <button className={`uc-tab-btn ${sub==='received' ? 'active' : ''}`} onClick={() => setSub('received')}>Received</button>
      </div>
      {sub === 'send'     && <SendTab />}
      {sub === 'received' && <ReceivedTab />}
    </div>
  )
}
